package net.civeira.phylax.feature.oauth.profile.infrastructure.driven;

import java.util.Optional;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.crypto.PasswordHasher;
import net.civeira.phylax.feature.identity.tenant.domain.Tenant;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantFilter;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.user.domain.User;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserCommandRepositoryGateway;
import net.civeira.phylax.feature.identity.user.domain.gateway.UserFilter;
import net.civeira.phylax.feature.oauth.profile.domain.gateway.PasswordGateway;

/**
 * Stub adapter for profile password change.
 *
 * <p>
 * Marked {@code @Vetoed} — replace with a real implementation that verifies the old password and
 * updates the hash via the access/user BC.
 * </p>
 */
@ApplicationScoped
@RequiredArgsConstructor
public class PasswordAdapter implements PasswordGateway {

  private final UserCommandRepositoryGateway users;
  private final TenantQueryRepositoryGateway tenants;
  private final PasswordHasher passwordHasher;

  @Override
  public boolean changePassword(String userUid, String tenant, String oldPass, String newPass) {
    Optional<User> found = users.findForUpdate(UserFilter.builder().uid(userUid).build());
    if (found.isEmpty()) {
      return false;
    }
    User user = found.get();
    Optional<Tenant> tenantObj = tenants.find(TenantFilter.builder().name(tenant).build());
    if (tenantObj.isEmpty() || !tenantObj.get().getUid().equals(user.getTenantUid())) {
      return false;
    }
    if (!user.verify(passwordHasher, oldPass)) {
      return false;
    }
    users.update(user, user.changePassword(newPass));
    return true;
  }
}
